select pg_temp.b_fail($q$select public.install_system_bundle('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','bundle-lifecycle-owner@example.test','bb000000-0000-4000-8000-000000000021',(select id from b_source),'bb000000-0000-4000-8000-000000000010',1,'bb000000-0000-4000-8000-000000000040','Complete intake',pg_temp.b_targets(),null,1,1,jsonb_set(value->'ownerParts','{2,document,nodes}', '{}'::jsonb),value->'ownerState') from bundle_native_input$q$,'system_bundle_website_invalid');
select pg_temp.b_assert((select count(*)=0 from public.system_bundle_installations),'later website failure rolls back earlier app inquiry and lineage drafts');

