select pg_temp.b_fail($q$select pg_temp.b_install('bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test','bb000000-0000-4000-8000-000000000031',1,'agencyParts','agencyState')$q$,'business_record_access_denied');
select public.grant_system_bundle_targets('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000002','bundle-lifecycle-owner@example.test',id,pg_temp.b_targets()) from public.system_package_install_grants where command_id='bb000000-0000-4000-8000-000000000031';
