select pg_temp.b_fail($q$select public.read_system_bundle_targets('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test','bb000000-0000-4000-8000-000000000021','bb000000-0000-4000-8000-000000000031',pg_temp.b_targets())$q$,'business_record_access_denied');
