select pg_temp.b_assert(cardinality(public.system_bundle_read_work_ids('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test'))=3,'exact completed grant grants read of installed drafts');
select pg_temp.b_fail($q$select public.website_document_assert_actor('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000104','bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test',false,true)$q$,'workspace_access_denied');
select pg_temp.b_assert(not public.system_in_scope('bb000000-0000-4000-8000-000000000011','saved_work','bb000000-0000-4000-8000-000000000104',(public.system_actor_scope('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test',true)).work_ids),'completed receipt removes transient System writer');
