select pg_temp.b_assert(cardinality(public.system_bundle_read_work_ids('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test'))=0,'revocation closes installed draft read access');
