select public.commit_website_document_candidate('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100','bb000000-0000-4000-8000-000000000002','bundle-lifecycle-owner@example.test',2,2,value->>'confirmedHash',value->'confirmedDocument',value->'confirmedPayload') from bundle_native_input;
