select pg_temp.b_assert(public.reconcile_bundle_native_releases('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100')=0,'accepted but unreadback website stays unverified');
select public.record_website_document_health('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100',3,value->>'confirmedHash',clock_timestamp(),'hash_mismatch',repeat('f',64)) from bundle_native_input;
