select pg_temp.b_assert(public.reconcile_bundle_native_releases('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100')=1,'owner accepted exact FAQ and healthy native readback reconcile one Version release');
select pg_temp.b_assert(public.reconcile_bundle_native_releases('bb000000-0000-4000-8000-000000000011','bb000000-0000-4000-8000-000000000100')=0,'verified native receipt repair replays without provider writes');
select pg_temp.b_assert((select current_release=1 and row_revision=2 from public.system_versions where id=(select version_id from b_site_version)),'only accepted verified component advances independent Version');
update public.inquiry_workspaces set state=value->'publishedState',revision=revision+1 from bundle_native_input where business_id='bb000000-0000-4000-8000-000000000011';
select pg_temp.b_assert(public.reconcile_bundle_inquiry_releases('bb000000-0000-4000-8000-000000000011',(select value->'publishedWork'->>'capabilityId' from bundle_native_input))=0,'unproven fake state without native acceptance claim creates no release');
savepoint foreign_native_claim;
insert into public.inquiry_publication_claims(tenant_id,tenant_stable_id,business_id,request_id,capability_id,change_id,action,version,idempotency_key,command_digest,claim_token_hash,status,acceptance_id,actor_id,accepted_at) select t.id,t.stable_id,'bb000000-0000-4000-8000-000000000011',value->'publishedWork'->>'id',value->'publishedWork'->>'capabilityId','foreign-native-change','make_live',(value->'publishedWork'->'publishApproval'->>'version')::integer,'fictional-native-claim',repeat('c',64),repeat('d',64),'accepted','fictional-native-inquiry-acceptance','bb000000-0000-4000-8000-000000000002',clock_timestamp() from public.tenants t cross join bundle_native_input where t.id='bundle-target';
-- Injection is fictional transport evidence; acceptance must precede exact verification.
update public.inquiry_workspaces set state=jsonb_set(state,'{changes}',(select jsonb_agg(case when ch->>'id'=(select value->'publishedWork'->>'lastLiveChangeId' from bundle_native_input) then jsonb_set(ch,'{verification,checkedAt}',to_jsonb(clock_timestamp())) else ch end) from jsonb_array_elements(state->'changes') ch)) where business_id='bb000000-0000-4000-8000-000000000011';
