select pg_temp.b_assert(public.reconcile_bundle_inquiry_releases('bb000000-0000-4000-8000-000000000011',(select value->'publishedWork'->>'capabilityId' from bundle_native_input))=0,'inquiry verified receipt replays without a provider retry');
select pg_temp.b_assert((select count(*)=2 from public.system_version_releases r join public.system_versions v on v.id=r.version_id where v.business_workspace_id='bb000000-0000-4000-8000-000000000011'),'only native accepted verified inquiry and FAQ release, app remains draft');
select public.publish_system_version_source_revision('bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test',jsonb_build_object('source',jsonb_build_object('businessId','bb000000-0000-4000-8000-000000000010','systemId',(select id from b_source),'revisionId','bb000000-0000-4000-8000-000000000022','number',2),'definition',value->'definition2','declaration',public.system_package_behavior(value->'definition2','{}'),'summary','Qualified component update','requires','{"bindingKinds":[]}'::jsonb,'publishedBy','bb000000-0000-4000-8000-000000000001','publishedAt',now())) from bundle_native_input;
select public.record_system_bundle_qualification('bb000000-0000-4000-8000-000000000010','bb000000-0000-4000-8000-000000000001','bundle-lifecycle-agency@example.test','bb000000-0000-4000-8000-000000000022',value->'artifacts2') from bundle_native_input;
create temp table b_site_adoption as select public.read_system_version('bb000000-0000-4000-8000-000000000002','bundle-lifecycle-owner@example.test',version_id) lineage from b_site_version;
