select pg_temp.b_fail($q$select public.save_system_version('bb000000-0000-4000-8000-000000000002','bundle-lifecycle-owner@example.test',(select version_id from b_site_version),2,lineage) from b_site_adoption$q$,'system_revision_not_qualified');
